"""Manual reproducible: fuentes fijadas, HTML copiable, PDF y ZIP por etapas.
Requiere Python, PyMuPDF y Playwright con /usr/bin/chromium. No modifica la aplicación.
"""
from pathlib import Path
import subprocess, html, json, hashlib, zipfile, re, ast, textwrap
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[2]
OUT=Path(__file__).resolve().parent
REV='5b61028' # versión exacta de la aplicación y documentación que se estudia
FULL=subprocess.check_output(['git','rev-parse',REV],cwd=ROOT,text=True).strip()
BASE=f'https://github.com/Nikol235/Garritas-/blob/{FULL}/'
FILES=[p for p in subprocess.check_output(['git','ls-tree','-r','--name-only',FULL],cwd=ROOT,text=True).splitlines() if not p.startswith(('docs/','overrides/')) and Path(p).name!='.env']
DATA={p:subprocess.check_output(['git','show',f'{FULL}:{p}'],cwd=ROOT) for p in FILES}
# Solo se usa el diccionario de explicaciones; no se ejecuta el generador antiguo.
tree=ast.parse((ROOT/'docs/manuales/fuentes/generar.py').read_text())
SPECIAL={}
for n in tree.body:
    if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='SPECIAL' for t in n.targets): SPECIAL=ast.literal_eval(n.value)
NAMES=['Identidad y herramientas','Biblioteca común','Config Server','Eureka','Keycloak','Kafka','Catálogo','Institución','Usuario','Bienestar','Envío y tarifas','Venta y Saga','Pago','Citas','Gateway','Angular','Observabilidad','Automatización y entrega']
DOMAINS=['catalogo','institucion','usuario','bienestar','envio','venta','pago','citas']
def stage(p):
    if p.startswith('infra/garritas-common/'): return 2
    if p.startswith('infra/garritas-config/'): return 3
    if p.startswith('infra/garritas-eureka/'): return 4
    if p.startswith('keycloak/'): return 5
    if p.startswith('kafka/'): return 6
    for i,d in enumerate(DOMAINS,7):
        if p.startswith(f'services/garritas-{d}-ms/'):return i
    if p.startswith('infra/garritas-gateway/'):return 15
    if p.startswith('clients/'):return 16
    if p.startswith('obs/'):return 17
    if p.startswith(('uso-rapido/','.github/')):return 18
    return 1
STAGES={i:[] for i in range(1,19)}
for p in FILES:STAGES[stage(p)].append(p)
def order(p):
    s=Path(p)
    if s.name=='pom.xml':return (0,p)
    if '/db/migration/' in p:return (1,re.sub(r'V(\d+)',lambda m:f'V{int(m[1]):03}',p))
    if '/db/demo/' in p:return (2,p)
    for i,part in enumerate(['/entity/','/dto/','/repository/','/mapper/','/service/','/client/','/messaging/','/controller/','/config/','/exception/','/filter/']):
        if part in p:return (3+i,p)
    return (20,p)
for paths in STAGES.values(): paths.sort(key=order)
def esc(s):return html.escape(str(s))
def para(s):return '<p>'+s+'</p>'
def pre(s,lang='powershell'):return f'<div class="codebox"><button class="copy" type="button">Copiar código</button><pre data-lang="{esc(lang)}"><code>{esc(textwrap.dedent(s).strip(chr(10)))}</code></pre></div>'
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def steps(items):return '<ol>'+''.join('<li>'+x+'</li>' for x in items)+'</ol>'
def note(s):return '<aside>'+s+'</aside>'
def diagram(name,caption):
    s=(ROOT/'docs/guia-estudio-catalogo-usuario/diagramas'/f'{name}.svg').read_text();s=s[s.index('<svg'):]
    return '<figure>'+s+'<figcaption>'+caption+'</figcaption></figure>'
def pathlink(p):assert p in DATA,p;return f'<a class="path" href="{BASE}{p}">{esc(p)}</a>'
def source(p):
    return pathlink(p)+pre(DATA[p].decode(),Path(p).suffix.lstrip('.'))
def description(p):
    s=Path(p);stem=s.stem
    extra={
      'SuscripcionService':'Orquesta contratar, renovar y cancelar. Protege suscripción y período en una transacción local; consulta bloqueos y clave de idempotencia en el código. No ejecuta cobro bancario.',
      'PrestacionService':'Gestiona servicios individuales, paquetes y la oferta por sede: precio, duración y disponibilidad. Impide componentes duplicados o paquetes anidados inválidos.',
      'DespachoService':'Gestiona el despacho operativo ligado a una venta con envío cobrado. No permite convertir un recojo pagado en un envío gratis.',
      'VentaService':'Valida propietario, sede, productos y tarifa mediante consultas remotas. Guarda venta, detalles y Outbox en una transacción local; el pago se confirma después mediante eventos.',
      'CitaService':'Reserva servicios para una mascota del usuario, valida oferta de sede y profesional, conserva importes/duración y evita solapamientos. Sus llamadas remotas no son todas Feign.',
      'CartStore':'Guarda productos/cantidades y prepara el checkout. Conserva borrador de entrega y clave de reintento; los precios definitivos los valida Venta. No guarda el JWT en localStorage.',
      'InventarioEvents':'Consume eventos de la Saga: reserva inventario y libera unidades al compensar. Comprueba Inbox y la reserva por venta para resistir duplicados.',
      'VentaEvents':'Aplica cambios de estado a partir de eventos. Un pago aprobado crea el despacho cobrado; un rechazo después de reservar inicia compensación.',
      'PagoEvents':'Simula aprobación o rechazo de pago después de inventario reservado. TRANSFERENCIA es el rechazo didáctico, sin conexión a un banco.'
    }
    if stem in extra:return extra[stem]
    if stem in SPECIAL:return SPECIAL[stem]
    if p.endswith('package-lock.json'):return 'Lock generado por npm. Mantiene el árbol exacto de dependencias; cópialo desde el ZIP y ejecuta npm ci, no lo escribas ni actualices al azar.'
    if s.name in ('mvnw','mvnw.cmd') or '/.mvn/' in p:return 'Maven Wrapper oficial versionado. Copia el archivo exacto del ZIP; permite compilar sin instalar Maven globalmente.'
    if stem.endswith('Application'):return 'Entrada del módulo: main inicia SpringApplication.run. Las anotaciones activan funciones y las importaciones incorporan los componentes comunes.'
    if '/src/test/' in p or '.spec.' in p:return 'Prueba automatizada: lee los escenarios y aserciones para entender qué garantiza. Su ejecución puede requerir PostgreSQL según el caso.'
    if stem.endswith('Controller'):return 'Entrada HTTP: @RequestMapping define el prefijo; @GetMapping, @PostMapping, @PutMapping y @DeleteMapping declaran operaciones. Recibe DTO y delega al servicio.'
    if stem.endswith('Repository'):return 'Interfaz Spring Data para la tabla local. Spring genera la implementación; sus consultas y bloqueos son importantes para la consistencia.'
    if '/entity/' in p:return 'Modelo persistente local: @Entity y @Table identifican la tabla, @Id la clave y las relaciones vinculan tablas de esta misma base. Un id remoto no crea una FK entre microservicios.'
    if '/dto/' in p:return 'Contrato de entrada o salida de la API. Las validaciones limitan datos; no se expone todo el grafo de entidades JPA al navegador.'
    if stem.endswith('Mapper'):return 'Conversión entre entidad y DTO. Mantiene separado el modelo de almacenamiento del contrato HTTP.'
    if stem.endswith('Service'):return 'Reglas de negocio y coordinación de repositorios. @Transactional delimita cambios locales; no engloba todas las bases de la Saga.'
    if s.suffix=='.sql':return 'Migración Flyway: crea o evoluciona tablas/datos. V se ejecuta una vez en orden; R se reaplica al cambiar. No edites una V aplicada a una base compartida.'
    if s.name=='pom.xml':return 'Manifiesto Maven: artifactId, dependencias, versiones compatibles y plugins. La biblioteca de carpeta garritas-common tiene artifactId garritas-distributed.'
    if s.suffix=='.ts':return 'Lógica Angular: tipos, signals, eventos, formularios o acceso HTTP según el archivo. Se compila con Angular CLI.'
    if s.suffix=='.html':return 'Plantilla Angular: texto, estructura, enlaces y condiciones de presentación. El backend conserva la autorización efectiva.'
    if s.suffix=='.css':return 'Estilos globales: tamaños, colores, espaciado y adaptación móvil. Usa selectores acotados para cambiar solo una pantalla.'
    if s.name.startswith('compose'):return 'Docker Compose: imágenes, servicios, puertos host:contenedor, healthchecks, volúmenes y redes. DEV y despliegue integrado son modos alternativos.'
    if s.suffix in ('.yml','.yaml','.json'):return 'Configuración declarativa. Conserva las claves, comillas y sangría; el archivo decide qué proceso lee estos valores.'
    return 'Archivo de soporte versionado. La ruta y el contenido completo permiten reconstruir la misma versión sin depender de archivos locales ocultos.'
CSS='''@page {size:A4;margin:16mm 14mm 17mm}*{box-sizing:border-box}body{font:16px/1.65 Arial,sans-serif;color:#19352e;background:#f2f6f3;margin:0}main{max-width:1120px;margin:32px auto;background:white;padding:44px 55px}h1{font-size:30px;line-height:1.2;color:#135c47}h2{font-size:24px;line-height:1.3;color:#135c47;margin-top:32px}h3{font-size:19px;line-height:1.4}p,li{overflow-wrap:anywhere}a{color:#006b80}code,.path{font-family:monospace;font-size:.92em}.path{display:block;overflow-wrap:anywhere;margin:10px 0}pre{font:13px/1.5 'DejaVu Sans Mono',monospace;white-space:pre-wrap;overflow-wrap:anywhere;tab-size:2;background:#f1f5f3;padding:18px;border:1px solid #d9e5df;margin:0}pre code{font:inherit;white-space:inherit}.codebox{position:relative;margin:12px 0 22px}.copy{display:block;margin-left:auto;background:#135c47;color:white;border:0;border-radius:5px;padding:8px 12px;cursor:pointer}aside{background:#fff6d9;border-left:5px solid #dfac31;padding:15px;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:14px;margin:18px 0}td,th{border:1px solid #cbded4;padding:9px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#dfede5}figure{margin:24px 0}figure svg{width:100%;height:auto;max-height:680px}figcaption{font-size:13px;color:#52675f}.chapter{margin-top:55px;padding-top:20px;border-top:2px solid #d8e7df}.cover{padding:60px 0}.eyebrow{letter-spacing:2px;font-size:12px;color:#54796a}.toc a{display:block;padding:5px}.file{border-top:1px solid #cddfd4;margin-top:38px;padding-top:15px}.file h3{font-size:18px}.tools{position:sticky;top:0;background:#dfede5;padding:10px;z-index:1}.small{font-size:13px}input{padding:10px;width:70%}.hidden{display:none}@media print{body{background:white;font-size:10.5pt;line-height:1.5}main{padding:0;margin:0;max-width:none}.tools,.copy,.search{display:none!important}.chapter{break-before:page;margin:0;padding:0;border:0}.cover{break-after:page;padding-top:50mm}h1{font-size:25pt}h2{font-size:18pt}h3{font-size:13pt}h1,h2,h3,.path{break-after:avoid}pre{font-size:7.4pt;line-height:1.4;padding:8px;border:0}a{color:inherit;text-decoration:none}table{font-size:8.6pt}thead{display:table-header-group}tr{break-inside:avoid}.file{break-before:auto;margin-top:22px;padding-top:12px;border-top:1px solid #cddfd4}.file .eyebrow{break-after:avoid}pre{orphans:4;widows:4}figure{break-inside:avoid}figure svg{max-height:210mm}.hidden{display:block}.toc{font-size:10pt}}'''
JS='''document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{let t=b.parentElement.querySelector('code').textContent;try{await navigator.clipboard.writeText(t);b.textContent='Copiado';setTimeout(()=>b.textContent='Copiar código',1500)}catch(e){let a=document.createElement('textarea');a.value=t;document.body.append(a);a.select();let ok=document.execCommand('copy');a.remove();b.textContent=ok?'Copiado':'Selecciona el bloque y usa Ctrl+C'}});let q=document.querySelector('#buscar');if(q)q.oninput=()=>{let s=q.value.toLowerCase();document.querySelectorAll('.file').forEach(x=>x.classList.toggle('hidden',!x.dataset.path.toLowerCase().includes(s)))};'''
def document(title,body):return '<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><style>'+CSS+'</style><div class="tools"><button onclick="window.print()">Imprimir / guardar PDF</button> · Garritas Store · código copiable</div><main>'+body+'</main><script>'+JS+'</script></html>'
CH=[]
def chapter(title,body):CH.append((title,body))
chapter('1. Antes de empezar: qué vas a construir',para('Vas a reconstruir <b>Garritas Store</b>, una tienda de mascotas con compras, citas, sedes, logística, cuentas y suscripciones. Empezarás con una carpeta vacía. Crearás archivos en rutas exactas y entenderás por qué existen antes de ejecutarlos.')+para('La guía sigue el enfoque del ingeniero Ángel Sullon Macalupu en Pagatu, sesiones 1 a 11: servicio REST, configuración, descubrimiento, Gateway, resiliencia, seguridad, eventos, consistencia, observabilidad y frontend. Se adapta el dominio; no se atribuye a Garritas una copia literal de Pagatu.')+note('Este manual enseña la versión final de cada archivo. Las etapas tempranas todavía no constituyen un sistema completo: algunos módulos necesitan la configuración y las dependencias de etapas posteriores. En cada punto se indica qué puedes comprobar. No se inventa un historial de versiones intermedias.')+para(f'Código de referencia fijo: <code>{FULL}</code>. Los bloques completos y el ZIP se extraen de ese commit, no de una carpeta con cambios sin guardar. La base docente consultada es Pagatu <code>9e6fc30a7028c9398641d187b30da98117a5fc76</code>.')+table(['Entrega','Cómo usarla'],[['00-Manual-paso-a-paso.html / PDF','Leer en orden; los capítulos indican qué anexo y archivos crear.'],['01-Codigo-completo.html','Buscar una ruta, abrir su ficha y copiar TODO el bloque al archivo indicado.'],['02…05 PDF de código','Mismos archivos imprimibles, separados para no manejar un solo PDF enorme.'],['Garritas-desde-cero.zip','Fuentes exactas, instalador por etapas, índice, manifiesto y comandos. No contiene node_modules, targets ni bases de datos.']])+para('Usa el HTML para pegar código: el botón copia el texto original, sin números de línea. El PDF permite seleccionar texto, pero un lector puede introducir saltos visuales. Para archivos generados como package-lock.json y Maven Wrapper, copia el original del ZIP.'))
chapter('2. Qué significa cada nombre',table(['Nombre','Valor','Qué representa'],[['Proyecto','Garritas Store','Nombre de la tienda y de la documentación.'],['Carpeta de aprendizaje','Garritas-desde-cero','Directorio local; no tiene que llamarse igual que GitHub.'],['Repositorio original','Nikol235/Garritas-','Historial compartido; rama feat/garritas-store.'],['groupId','pe.edu.upeu','Organización Maven.'],['Paquete Java de Catálogo','pe.edu.upeu.garritas.catalogo','Se corresponde con src/main/java/pe/edu/upeu/garritas/catalogo.'],['artifactId / nombre lógico','garritas-catalogo-ms','Identifica el artefacto y spring.application.name; Config y Eureka necesitan nombres coherentes.'],['Biblioteca común','garritas-distributed','ArtifactId del JAR cuya carpeta es infra/garritas-common. No es un noveno microservicio de negocio.']])+para('Puedes elegir otro nombre visible para tu tienda, pero para reproducir esta guía conserva los identificadores técnicos. Renombrar solo la carpeta es sencillo; renombrar application.name obliga a revisar POM, config-repo, rutas lb://, Feign y observabilidad.'))
chapter('3. Instalar y verificar en Windows',steps(['Instala Git for Windows, Temurin JDK 21, Node 24 compatible con Angular 22 y Docker Desktop. Abre Docker Desktop y espera a que el motor esté activo.','Si instalas Docker por primera vez, sigue su asistente para habilitar WSL2 y reinicia Windows cuando lo solicite. WSL debe funcionar antes de iniciar los contenedores.','Instala VS Code. Cierra y abre PowerShell después de instalar herramientas: una consola vieja conserva el PATH anterior.'])+pre('''winget install --id Git.Git --exact
winget install --id EclipseAdoptium.Temurin.21.JDK --exact
winget install --id OpenJS.NodeJS.LTS --exact --version 24.22.1
winget install --id Docker.DockerDesktop --exact
winget install --id Microsoft.VisualStudioCode --exact''')+note('Estos comandos son de instalación inicial. Si ya tienes una herramienta, verifica su versión antes de reinstalar. Si winget no ofrece Node 24.22.1, usa una versión 24.15 o superior de la rama 24.x; no cambies de major sin comprobar Angular. Docker Desktop puede pedir permisos de administrador.')+pre('''git --version
java -version
javac -version
node --version
npm.cmd --version
docker compose version
docker info
wsl --status''')+para('Java y javac deben indicar 21. Node debe ser 24.x compatible. docker info debe mostrar <b>Server</b> sin error de arranque. Tener el comando docker instalado no demuestra que el motor funcione. Maven global no es obligatorio: usamos mvnw.cmd. No se necesita Angular CLI global.')+para('Si node funciona en CMD pero no en PowerShell, abre una consola nueva y ejecuta Get-Command node. No cambies el código para corregir un PATH de Windows.'))
chapter('4. Crear tu carpeta y tu repositorio vacío',para('Trabaja en una carpeta nueva para evitar mezclar una copia antigua, Pagatu y tu construcción. Estos comandos no clonan Garritas: crean tu propio punto de partida.')+pre('''cd $HOME
New-Item -ItemType Directory -Force proyectos | Out-Null
cd proyectos
New-Item -ItemType Directory -Force Garritas-desde-cero | Out-Null
cd Garritas-desde-cero
git init
git branch -M main
New-Item -ItemType Directory -Force infra, services, clients, kafka, keycloak, obs, uso-rapido | Out-Null
code .''')+para('Estás en la raíz si ves infra, services y clients juntos. Todas las rutas de los anexos se interpretan desde aquí. En VS Code usa Ctrl+P y pega la ruta del archivo; el buscador no crea archivos inexistentes.')+pre('''# Ejemplo de carpeta y archivo NUEVO; no ejecutar sobre código ya escrito.
New-Item -ItemType Directory -Force services/garritas-catalogo-ms/src/main/java/pe/edu/upeu/garritas/catalogo/entity | Out-Null
New-Item -ItemType File services/garritas-catalogo-ms/src/main/java/pe/edu/upeu/garritas/catalogo/entity/Categoria.java
code services/garritas-catalogo-ms/src/main/java/pe/edu/upeu/garritas/catalogo/entity/Categoria.java''')+para('Pega el contenido de esa ficha y guarda en UTF-8. No pegues títulos, rutas o marcas de Markdown dentro del archivo. Java exige nombre de clase pública igual al archivo y package coherente con la carpeta.'))
chapter('5. Cómo usar los archivos y avanzar sin perderte',para('Descarga y extrae Garritas-desde-cero.zip en Descargas. El directorio extraído tiene FUENTES (código), ETAPAS (listas de rutas), MANIFIESTO.json y copiar-etapa.ps1. Puedes escribir cada archivo manualmente desde el HTML o copiar una etapa completa y luego estudiar sus archivos. Ambas rutas llevan al mismo código.')+pre('''# Ajusta solo esta ruta al lugar donde extrajiste el ZIP.
$material = "$HOME\\Downloads\\Garritas-desde-cero"
$destino = "$HOME\\proyectos\\Garritas-desde-cero"
Set-ExecutionPolicy -Scope Process -ExecutionPolicy RemoteSigned -Force
Unblock-File -LiteralPath "$material\\copiar-etapa.ps1"
& "$material\\copiar-etapa.ps1" -Etapa 1 -Destino $destino''')+para('El ayudante crea carpetas y copia archivos que faltan. Si encuentra un archivo distinto, se detiene para no sobrescribir tu trabajo; si es idéntico lo conserva. No inicia servicios ni modifica Git. Para la etapa 2 cambia -Etapa 1 por -Etapa 2, y así hasta 18. Si prefieres pegar todo a mano, cada ficha tiene un comando para crear el archivo sin sobrescribir uno existente.')+note('No ejecutes el instalador de una etapa después de personalizar sus archivos sin revisar diferencias. El objetivo es aprender por partes; no necesitas copiar las 18 etapas de golpe.')+table(['Etapa','Qué se crea'],[[str(i),n] for i,n in enumerate(NAMES,1)]))
chapter('6. Mapa del sistema y de las carpetas',diagram('c1-contexto','C4 nivel 1: personas, tienda e identidad. El pago del laboratorio es simulado.')+para('El frontend es una aplicación Angular. Gateway recibe las peticiones de negocio; cada dominio mantiene su base PostgreSQL. Config Server entrega propiedades. Eureka mantiene instancias. Kafka desacopla la compra, el inventario y el pago. Keycloak autentica. Grafana consulta métricas en Prometheus y logs en Loki.')+pre('''Garritas-desde-cero/
  infra/garritas-common/     # JAR compartido
  infra/garritas-config/     # Config Server y config-repo
  infra/garritas-eureka/     # registro de servicios
  infra/garritas-gateway/    # entrada de API
  services/garritas-*-ms/    # ocho dominios y ocho bases
  clients/garritas-frontend/# aplicación Angular
  kafka/                    # broker y Kafka UI
  keycloak/                 # identidad y realm
  obs/                      # métricas, logs y dashboard
  uso-rapido/                # reactor Maven y automatización''','text')+note('Un contenedor C4 significa una aplicación o almacén ejecutable. No implica que cada caja deba ejecutarse en Docker. En DEV, Java y Angular corren en Windows; Docker aloja las bases y herramientas.'))
chapter('7. Etapa 1: archivos raíz y contratos de versión',para('Crea los archivos listados en ETAPAS/01.txt o en el índice de código. .gitignore evita subir builds, dependencias y archivos privados; .java-version y .nvmrc documentan versiones para herramientas que los lean. Por sí solos no instalan Java ni Node.')+para('El pom.xml agregador estará en uso-rapido, no en la raíz. No intentes compilar el reactor antes de crear todos los módulos: Maven fallará si una ruta declarada todavía no existe.')+pre('''git status
# Al cerrar una etapa que entiendas:
git add .
git commit -m "Crear estructura inicial de Garritas"''')+para('Si Git pide identidad por primera vez, configura tu propio nombre y correo con git config user.name y git config user.email antes del commit. Un commit local no publica nada en GitHub.'))
chapter('8. Crear un microservicio: Initializr y lectura del POM',para('Spring Initializr genera el esqueleto de una aplicación. Puedes abrir start.spring.io y reconocer los campos, pero para reproducir esta versión usa los POM y wrappers exactos del anexo: las versiones disponibles hoy en Initializr pueden ser distintas.')+table(['Campo','Selección de referencia'],[['Project / Language','Maven / Java'],['Group','pe.edu.upeu'],['Artifact / Name','garritas-catalogo-ms'],['Package name','pe.edu.upeu.garritas.catalogo'],['Packaging / Java','Jar / 21'],['Framework del código','Spring Boot 4.0.8 y BOM Spring Cloud 2025.1.3'],['Dependencias de negocio','Web MVC, JPA, Validation, PostgreSQL, Flyway, Actuator, Config Client, Eureka Client, Resource Server; Kafka solo donde se utiliza.']])+para('En cada módulo crea pom.xml, src/main/java y src/main/resources. Copia .mvn, mvnw y mvnw.cmd del ZIP. No escribas los wrappers a mano ni uses el mismo POM para Config, Eureka y Gateway: cada aplicación necesita starters diferentes.')+para('En el POM, parent fija Spring Boot; dependencyManagement importa el BOM de Spring Cloud. dependencies declara bibliotecas, no servicios remotos. El plugin de Spring Boot empaqueta el JAR ejecutable. El JAR común se agrega como dependencia a los módulos que lo importan.'))
chapter('9. Etapa 2: la biblioteca común',para('Crea infra/garritas-common con todos los archivos de la etapa 2. Estudia primero Reference y SagaEvent; sigue con CurrentUser y SecurityConfiguration; después ServiceClient, HttpServices, DomainErrors, Inbox, Outbox y MessagingConfiguration.')+table(['Clase','Qué resuelve'],[['CurrentUser','Lee sub/roles del JWT autenticado y comprueba propiedad.'],['SecurityConfiguration','Configura Resource Server, permisos y conversión de roles; no reemplaza a Keycloak.'],['ServiceClient / HttpServices','Consultas HTTP entre servicios con descubrimiento, token, correlación y espera acotada.'],['SagaEvent','Contrato de eventos con tipo, identificadores, versión, items y trazabilidad.'],['Inbox / Outbox','Registra consumo y publicación de eventos junto al cambio local.'],['MessagingConfiguration','Configura Kafka, reintentos y DLT.'],['DomainErrors','Traduce errores de dominio a respuestas HTTP.']])+para('Las clases comunes solo se activan donde las aplicaciones las importan. Estar en un JAR no registra automáticamente cada componente. Usuario no se convierte en consumidor Kafka por depender de la biblioteca.')+pre('''.\\infra\\garritas-config\\mvnw.cmd -f infra/garritas-common/pom.xml -B install -DskipTests''')+note('Este comando requiere haber copiado el wrapper de Config, disponible en la etapa 3. Puedes copiar únicamente sus archivos mvnw/.mvn desde FUENTES antes de ejecutarlo. Resultado esperado: BUILD SUCCESS y JAR común instalado en .m2. No necesita arrancar las ocho bases.'))
chapter('10. Etapa 3: Config Server y configuración central',steps(['Crea infra/garritas-config con su POM, wrapper, clase principal y application.yml.','Copia todos los YAML de config-repo, incluidas variantes DEV y PROD. Para trabajar aquí usaremos DEV.','Lee la clase @EnableConfigServer y la ubicación file:./config-repo. La carpeta de trabajo debe ser la del módulo al iniciarlo.'])+source('infra/garritas-config/src/main/resources/application.yml')+pre('''# Consola A: desde la raíz del proyecto.
cd infra/garritas-config
.\\mvnw.cmd spring-boot:run''')+pre('''# Otra consola, para comprobar que entrega la configuración.
Invoke-RestMethod http://localhost:18888/garritas-catalogo-ms/dev''')+para('Debes obtener un documento con propertySources. En el cliente, spring.application.name=garritas-catalogo-ms y spring.config.import=configserver:... determinan qué configuración solicitar. Se conserva la importación obligatoria: si Config no está disponible, no se continúa silenciosamente con propiedades incompletas.'))
chapter('11. Etapa 4: Eureka y descubrimiento',para('Crea infra/garritas-eureka y su configuración. La clase principal lleva @EnableEurekaServer. Inicia Config antes de Eureka. Cada instancia de negocio se registra con su nombre y puerto; Gateway y Feign usan esos nombres para descubrirla.')+pre('''# Consola B, desde la raíz; deja Config abierto.
cd infra/garritas-eureka
.\\mvnw.cmd spring-boot:run''')+pre('''Start-Process "http://localhost:18761"''')+para('La consola debe abrir aunque aún no existan servicios de negocio registrados. Eureka no contiene datos de productos ni enruta compras: publica el registro. La renovación de registros y la caché implican que los cambios no son instantáneos.'))
chapter('12. Etapa 5: Keycloak, realm y permisos',steps(['Crea keycloak/compose-dev.yml y keycloak/garritas-realm.json con el contenido completo del anexo.','El realm garritas contiene los roles CLIENTE y ADMIN, los usuarios de demostración y el cliente público garritas-frontend.','Ejecuta Compose. El import monta el JSON al arrancar; no actualiza automáticamente un realm ya existente.'])+pre('''# Desde la raíz, con Docker Desktop funcionando.
docker compose -f keycloak/compose-dev.yml up -d --wait --wait-timeout 240
Start-Process "http://localhost:18180/admin/"''')+table(['Acceso de laboratorio','Usuario','Contraseña inicial'],[['Consola Keycloak','admin','local-admin-change-me'],['Cliente Angular','cliente','Cliente123!'],['Administrador Angular','admin-store','Admin123!']])+para('En la consola selecciona realm garritas. En Realm roles comprueba CLIENTE y ADMIN; en Clients verifica garritas-frontend, redirecciones localhost:4200, PKCE S256 y el mapper de audiencia garritas-api. En Users puedes restablecer contraseñas si ya cambiaron en la base persistente.')+para('Cada API valida firma, issuer y audience. Los roles están en realm_access.roles. sub es una cadena estable del proveedor; no equivale al id numérico de una tabla Usuario. Los roles internos de la base de Usuario sirven para clasificación, no conceden privilegios JWT.')+diagram('jwt','Login: Angular obtiene un código mediante redirección y PKCE; intercambia el código y utiliza el JWT. Los servicios validan también peticiones directas.')+note('No pongas un client_secret en una SPA ni habilites contraseña directa para hacer el login más fácil. keycloak-js mantiene tokens en memoria. Las credenciales anteriores son únicamente las iniciales del laboratorio local.'))
chapter('13. Etapa 6: Kafka y mensajería',para('Crea kafka/compose-dev.yml y los demás archivos de su etapa. Kafka es un broker de eventos; Kafka UI es su interfaz de inspección. El puerto 19092 es TCP para clientes del host y 18085 corresponde a la página web.')+pre('''docker compose -f kafka/compose-dev.yml up -d --wait --wait-timeout 240
Start-Process "http://localhost:18085"''')+para('Las aplicaciones Java en Windows conectan a localhost:19092. Kafka UI, dentro de Docker, conecta al alias de red del broker: no usa localhost para otro contenedor. Mezclar esas direcciones causa fallos de conexión aunque el contenedor figure iniciado.')+para('El topic de negocio es garritas.ventas.v1. Venta, Catálogo y Pago tienen grupos distintos para que cada servicio reciba los eventos que necesita. El productor usa la venta como clave para mantener el orden de esa clave dentro de una partición. Tres particiones y una réplica son configuración de laboratorio, no alta disponibilidad.')+note('Si Pagatu ocupa 19092 o 18085, primero identifica el contenedor. Detén únicamente el contenedor de Pagatu que ocupa el puerto si no lo están utilizando tus compañeras. No borres volúmenes para resolver una colisión.'))
chapter('14. El patrón interno que repetirás ocho veces',table(['Capa / carpeta','Qué crear y por qué'],[['entity','Clases de tablas y relaciones JPA; no son el JSON público.'],['dto','Request y Response con contrato/validaciones.'],['repository','Interfaces de consultas, escrituras y bloqueos.'],['mapper','Conversión entidad ↔ DTO.'],['service','Reglas de negocio y límites de transacción.'],['controller','Endpoints HTTP y delegación al servicio.'],['exception / filter / config','Errores, correlación, Swagger y configuración del módulo.'],['src/main/resources','application.yml, db/migration y db/demo.'],['src/test/java','Pruebas de comportamiento e integración.']])+para('Orden recomendado al pegar: POM → SQL → entidades → DTO → repositorios → mappers → servicios → clientes/eventos si existen → controladores → configuración y clase Application → pruebas. Una clase puede marcar imports pendientes mientras aún faltan archivos; compila al completar el módulo y sus dependencias.')+para('Una petición GET entra por Controller, llama al Service, consulta al Repository y devuelve un DTO. Una operación de escritura valida primero, cambia la base dentro de una transacción y responde. @Valid activa Bean Validation; @Transactional define una transacción de esa base, no de todas las bases del sistema.')+table(['Código frecuente','Significado'],[['@RestController / @RequestMapping','Exponer JSON bajo una ruta.'],['@Entity / @Table / @Id','Mapear clase, tabla y clave.'],['@RequiredArgsConstructor','Lombok crea constructor para inyectar campos final.'],['JpaRepository','Spring implementa operaciones de persistencia.'],['@NotBlank / @Size / @Positive','Rechazar entradas inválidas.'],['@Transactional','Confirmar o revertir el conjunto de cambios locales según el resultado y las reglas de rollback.'],['@ManyToOne / @OneToMany','Una fila pertenece a otra; una cabecera tiene varios detalles.']]))
chapter('15. PostgreSQL y Flyway: crear las bases',para('Cada dominio trae compose-dev.yml para su PostgreSQL. No crees una única base compartida para los ocho servicios. Flyway aplica las migraciones al iniciar cada aplicación, antes de que JPA valide el esquema.')+pre('''# Ejemplo: al haber creado la etapa 7.
docker compose -f services/garritas-catalogo-ms/compose-dev.yml up -d''')+para('Copia TODAS las migraciones V1, V2, V3… que aparezcan en la etapa, no solo V1. Si una migración ya se aplicó, añadir una nueva V es preferible a modificar la anterior. R__ corresponde a migración repetible; los ejemplos peruanos de db/demo se cargan en DEV.')+para('En application.yml de cada servicio se importa Config. El datasource DEV apunta a localhost:1544x porque Java corre en Windows; el PostgreSQL escucha 5432 dentro de su contenedor. ddl-auto: validate comprueba el modelo, no crea las tablas automáticamente.')+note('No borres volúmenes ni hagas flyway repair como primer intento ante un error. Lee la migración, el checksum y la base concreta. Docker down -v elimina datos persistidos.'))
chapter('16. Etapa 7: construir Catálogo y tu primer CRUD',para('Catálogo administra categorías y productos; una categoría agrupa varios productos y un producto puede pertenecer a varias categorías. Además, Catálogo controla inventario y participa en la Saga, por lo que tiene comportamiento transaccional además de su papel maestro.')+steps(['Copia la etapa 7 en el orden indicado en el índice. Comienza por el SQL y las entidades Categoria y Producto.','Crea los DTO de entrada/salida. CategoriaRequest exige nombre y limita su longitud; ProductoRequest define precio, stock y categorías admitidas.','Crea repositorios, mappers y servicios. Revisa que los IDs de categorías existan y que no se acepte stock/precio inválido.','Crea CategoriaController y ProductoController. Los verbos GET/POST/PUT/DELETE implementan las operaciones expuestas.','Añade InventarioEvents, migraciones de reservas/Inbox/Outbox y configuración Kafka: forman parte de esta versión final.'])+source('services/garritas-catalogo-ms/src/main/java/pe/edu/upeu/garritas/catalogo/dto/CategoriaRequest.java')+para('Lee el controlador completo y relaciona cada anotación con la operación; el código de abajo es el archivo real, listo para pegar en la ruta indicada.')+source('services/garritas-catalogo-ms/src/main/java/pe/edu/upeu/garritas/catalogo/controller/CategoriaController.java')+pre('''# Consola C: con Config, Eureka, Keycloak, Kafka y PostgreSQL de Catálogo activos.
cd services/garritas-catalogo-ms
.\\mvnw.cmd spring-boot:run''')+pre('''# En otra consola.
Invoke-RestMethod http://localhost:8085/actuator/health/readiness
Invoke-RestMethod http://localhost:8085/api/v1/categorias
Start-Process "http://localhost:8085/swagger-ui.html"''')+para('Espera health UP y un listado, aunque esté vacío. Verifica el registro garritas-catalogo-ms en Eureka. La creación/modificación exige ADMIN; cuando Angular esté listo, inicia sesión como administrador y usa sus formularios o Swagger con un JWT válido. No conviertas una escritura protegida en pública para que el ejemplo funcione.')+diagram('c3-catalogo','C4 nivel 3 de Catálogo: REST, persistencia e inventario por eventos, con base propia.'))
# Un CRUD completo explicado antes de repetir el patrón en otros dominios.
cp='services/garritas-catalogo-ms/src/main/java/pe/edu/upeu/garritas/catalogo/'
lesson=para('Recorre una categoría desde la tabla hasta HTTP. Las clases siguientes son archivos completos del mismo proyecto, no pseudocódigo. Crea cada ruta indicada y pega su bloque; después localiza las instrucciones que se explican.')
for suffix,explain in [
 ('entity/Categoria.java','<b>Entidad:</b> package declara el espacio de nombres; imports trae tipos; @Entity registra el modelo JPA; @Table indica la tabla; @Id identifica una fila. @GeneratedValue permite generar su id. Lombok aporta métodos repetitivos, no reglas de negocio.'),
 ('repository/CategoriaRepository.java','<b>Repositorio:</b> extends JpaRepository indica entidad y tipo de clave. No escribes una clase con SQL para cada CRUD: Spring Data crea el bean. Las búsquedas adicionales se declaran en esta interfaz.'),
 ('mapper/CategoriaMapper.java','<b>Mapper:</b> lee campos del DTO y los coloca en una entidad, o construye el DTO de respuesta. No copies el id recibido del cliente para forzar la identidad de una entidad nueva.'),
 ('service/CategoriaService.java','<b>Servicio:</b> el constructor inyecta repositorio y mapper. listar/obtener consultan; crear/actualizar/eliminar aplican reglas. Busca @Transactional, findById y la excepción cuando no existe. Si lanza un error de ejecución dentro de su límite transaccional, se revierten los cambios locales según la configuración de rollback.')]:
 lesson+=para(explain)+source(cp+suffix)
lesson+=para('El controlador del capítulo anterior usa este servicio. El recorrido de crear es JSON → CategoriaRequest → @Valid → CategoriaService.crear → mapper → repository.save → tabla → CategoriaResponse → JSON. Ahora puedes reconocer el mismo recorrido en Sede, Transportista y otros maestros.')
chapter('16.1. Tu primer CRUD, explicado clase por clase',lesson)

chapter('17. Etapa 8: Institución, sedes y paquetes',para('Institución administra las sedes y lo que se ofrece en cada una. Crea Sede, Prestacion y SedePrestacion, sus DTO, repositorios, servicios y controladores. El catálogo de código de la etapa 8 incluye todos los archivos.')+table(['Modelo','Regla de negocio'],[['Sede','Dirección, contacto y disponibilidad de una sede. Los ejemplos de Perú vienen de db/demo.'],['Prestacion','Servicio individual o paquete. Un paquete agrupa componentes individuales válidos.'],['SedePrestacion','Asociación N:M con atributos: precio, duración y disponibilidad de la prestación en la sede.'],['prestacion_componentes','Asociación de paquetes con sus componentes. No es una FK entre servicios.']])+para('La N:M se explica así: una sede ofrece varios servicios y el mismo servicio se ofrece en varias sedes. La tabla de unión tiene sus propios datos, por eso se modela como entidad con dos @ManyToOne. No necesita literalmente @ManyToMany para ser una N:M relacional.')+para('Crea migraciones V1 a V3 y ejemplos repetibles. La oferta de baño + corte puede variar por sede: el cliente no debe elegir un precio inventado. Citas consulta la oferta vigente y guarda una copia del importe/duración para no alterar citas antiguas al cambiar el maestro.')+para('Para comprobar en Angular: ADMIN → Sedes y Prestaciones → crear servicio/paquete → asignarlo a una sede con precio y duración → CLIENTE → observar la oferta al reservar. Solo ADMIN administra; cliente consulta y selecciona.')+para(pathlink('services/garritas-institucion-ms/src/main/java/pe/edu/upeu/garritas/institucion/entity/SedePrestacion.java'))+para(pathlink('services/garritas-institucion-ms/src/main/java/pe/edu/upeu/garritas/institucion/service/PrestacionService.java')))
chapter('18. Etapa 9: Usuario, perfil, mascotas y suscripciones',para('Usuario vincula el sub de Keycloak con el perfil del negocio. No guarda contraseñas de login ni emite JWT. Crea las entidades, DTO, repositorios y servicios de usuarios, mascotas, roles internos, planes, suscripciones y períodos.')+steps(['Para perfil usa las rutas de /usuarios/me: el propietario sale del token, no de un sub enviado por el navegador.','Valida DNI de ocho dígitos y teléfono peruano, cuando se proporcione, de nueve dígitos empezando por 9. No uses una entrada numérica que elimine ceros o acepte notación científica.','Una mascota pertenece a su usuario. Guarda edad y unidad DIAS o MESES, no un número sin unidad.','Un plan es un maestro; contratarlo crea suscripción y primer período. Renovar cambia vigencia y agrega período histórico en una misma transacción.','Los precios históricos se conservan aunque cambie el precio del plan. Una suscripción cancelada no puede renovarse.'])+para('Hay N:M entre usuarios y roles internos, y entre usuarios y planes a través de suscripciones. Esas tablas no sustituyen los roles de Keycloak. Un cliente no debe poder obtener ADMIN editando un formulario de perfil.')+para('La capacidad transaccional defendible de Usuario es contratar/renovar suscripciones: se guardan juntas suscripción y período, con reglas, bloqueos y clave de idempotencia. Es una operación local; no es un cobro bancario ni participa automáticamente en la Saga de Venta.')+diagram('c3-usuario','C4 nivel 3 de Usuario: cuenta propia, mascotas, planes y suscripciones, todos con persistencia local.')+para('Prueba al completar Angular: CLIENTE → Mi cuenta → guardar datos → salir de la pantalla y volver a entrar; verifica lo recuperado del servidor. Crea mascota de 3 MESES. Contrata un plan, renueva y observa un nuevo período. Intenta renovar tras cancelar y espera rechazo.'))
chapter('19. Etapa 10: Bienestar y profesionales',para('Bienestar administra profesionales/especialistas y sus especialidades. Una profesional puede tener varias especialidades y una especialidad varios profesionales; la relación es N:M local. Citas consulta la referencia de profesional antes de reservar.')+para('Crea la etapa 10 completa. Las relaciones se verifican en entidades, DTO que transporta los IDs, servicio que resuelve dichos IDs y tabla intermedia de Flyway. No basta dibujar la línea entre dos cajas: confirma que al guardar y volver a consultar se conservan las asociaciones.')+para('Prueba: como ADMIN crea dos especialidades y vincúlalas a una profesional. Como cliente observa la profesional al preparar la cita. Si borras una especialidad todavía vinculada, el sistema debe respetar la restricción indicada por su servicio; no borres registros huérfanos manualmente.'))
chapter('20. Etapa 11: Envío y tarifas',para('El microservicio Envío administra transportistas, zonas y coberturas. La cobertura une transportista y zona con tarifa, días y disponibilidad. Es su N:M de negocio y constituye un maestro logístico.')+para('En esta versión, el despacho operativo de una venta se guarda en Venta, junto a la confirmación del pago y el importe del envío. El alias HTTP /envios llega a Venta por Gateway; /transportistas, /zonas y /coberturas llegan a Envío. No confundas el nombre de una pantalla con la base donde se guarda el despacho.')+steps(['Crea la etapa 11: entidades Transportista, Zona y Cobertura y sus capas REST.','Configura precio positivo/no negativo y disponibilidad según los DTO y servicios del código.','Como ADMIN registra cobertura entre transportista y zona.','Como cliente selecciona esa cobertura en checkout: su tarifa se suma al total. Venta vuelve a consultar y validar la tarifa en el servidor.'])+para('Una compra con recojo no puede convertirse después en un envío gratis. Si Envío no responde durante la cotización/validación, la compra falla de forma controlada antes de crear la venta. Esa situación es resiliencia, no compensación.'))
chapter('21. Etapa 12: Venta, cabecera y detalles',para('Venta recibe el checkout y coordina la compra. Crea Venta y DetalleVenta, DTO, repositorios, servicio, clientes remotos, eventos y despacho. Venta → detalles es 1:N; cada detalle guarda producto, cantidad y precio acordado.')+steps(['CLIENTE envía productos/cantidades, sede, entrega y método. ADMIN no compra, incluso si además tiene CLIENTE.','Venta verifica propietario, clave de idempotencia, sede, productos, stock observado y tarifa vigente. Nunca toma el total del navegador como autoridad.','Calcula subtotal + costo de envío. Persiste venta y detalles y añade venta.creada al Outbox en una transacción local.','Responde con la venta pendiente. No afirma que está pagada antes del evento de confirmación.','Los consumidores avanzan la Saga; Angular consulta pedidos hasta conocer el resultado.'])+para('La clave Idempotency-Key permite repetir un checkout sin crear dos ventas por la misma operación. Un bloqueo o restricción evita carreras: no es suficiente hacer un SELECT y luego un INSERT sin control concurrente.')+para(pathlink('services/garritas-venta-ms/src/main/java/pe/edu/upeu/garritas/venta/service/VentaService.java'))+para(pathlink('services/garritas-venta-ms/src/main/java/pe/edu/upeu/garritas/venta/messaging/VentaEvents.java'))+para(pathlink('services/garritas-venta-ms/src/main/java/pe/edu/upeu/garritas/venta/despacho/service/DespachoService.java'))+note('No uses una transacción JDBC de Venta para imaginar que también revierte la base de Catálogo o Pago. Hay tres bases independientes; el proceso global se coordina por eventos y compensación.'))
chapter('22. S6: llamadas síncronas, Feign y Circuit Breaker',para('Venta necesita respuestas inmediatas de Catálogo y Envío antes de aceptar el checkout. Sus clientes Feign usan nombres lógicos de Eureka. ProductoClient y LogisticaClient describen contratos; CatalogoConsulta y LogisticaConsulta aplican Circuit Breaker y respuesta de error controlada.')+table(['Mecanismo','Qué evita'],[['Timeout de conexión','Esperar indefinidamente para establecer la conexión.'],['Timeout de lectura','Esperar indefinidamente una respuesta de un destino lento.'],['Circuit Breaker','Seguir golpeando un destino que ya falla repetidamente; abierto rechaza rápido.'],['Error controlado / fallback','Propagar una respuesta comprensible. Aquí no inventa stock ni tarifas para vender igual.']])+para('La configuración de esta versión declara 2 s de conexión, 3 s de lectura, ventana de 10 llamadas, mínimo 5, umbral 50 % y apertura 10 s en los circuitos de Venta; consulta el YAML completo para los límites adicionales. Un timeout termina una llamada; un circuito recuerda resultados de varias llamadas.')+para('Citas y algunas referencias usan el ServiceClient común. No afirmes que todas las comunicaciones son Feign o tienen Circuit Breaker: verifica la clase que realiza cada llamada.')+para(pathlink('services/garritas-venta-ms/src/main/java/pe/edu/upeu/garritas/venta/client/ProductoClient.java'))+para(pathlink('services/garritas-venta-ms/src/main/java/pe/edu/upeu/garritas/venta/client/CatalogoConsulta.java'))+para(pathlink('infra/garritas-config/config-repo/garritas-venta-ms-dev.yml')))
chapter('23. Etapa 13: Pago simulado',para('Pago consume inventario.reservado y decide el resultado didáctico. Publica pago.validado o pago.fallido con el total calculado por Venta, incluido el envío. Sus escrituras y Outbox son locales; la idempotencia evita cobrar o publicar efectos de negocio repetidos.')+para('TRANSFERENCIA se usa para simular rechazo y demostrar compensación. Los otros métodos siguen las reglas que verás en PagoEvents. No hay integración bancaria, tarjeta real ni devolución bancaria automática. Es importante decirlo al sustentar.')+para('Crea toda la etapa 13, incluida la migración de mensajería. La existencia de PagoRequest no implica que un cliente pueda llamar un POST arbitrario para declarar pagada una venta. Lee los endpoints reales de PagoController y el consumidor.')+para(pathlink('services/garritas-pago-ms/src/main/java/pe/edu/upeu/garritas/pago/messaging/PagoEvents.java')))
chapter('24. S8 y S9: Saga, Outbox, Inbox y compensación',diagram('saga-compensacion','Compra distribuida: la compensación devuelve inventario reservado cuando el pago se rechaza.')+table(['Paso','Resultado local / evento'],[['1. Venta acepta','PENDIENTE_STOCK + venta.creada.'],['2. Catálogo reserva','Reserva única por venta + inventario.reservado; o inventario.rechazado si no puede reservar.'],['3. Venta y Pago continúan','Venta PENDIENTE_PAGO; Pago procesa el importe acordado.'],['4a. Pago aprobado','pago.validado → PAGADA; Venta crea un despacho único si el envío fue cobrado.'],['4b. Pago rechazado','pago.fallido → COMPENSANDO. Catálogo libera la reserva una vez.'],['5. Compensación confirmada','inventario.liberado → Venta CANCELADA.']])+para('Outbox guarda el evento en la misma transacción que el cambio local. Otro proceso lo publica y registra su envío tras confirmación. Un fallo entre publicar y registrar puede repetir el evento: por eso la garantía es al menos una vez, no exactamente una vez en todo el sistema.')+para('Inbox detecta eventId ya consumidos dentro de la transacción del consumidor. Además se necesitan reglas de negocio por idVenta: un duplicado semántico con otro eventId tampoco debe reservar o crear despacho otra vez. Las restricciones y estados de la reserva cubren ese caso.')+table(['Situación','Respuesta correcta'],[['No hay stock antes de aceptar','No se crea venta; no hay reserva que devolver.'],['Catálogo rechaza reserva posterior','La venta existente se cancela sin continuar al pago.'],['Pago rechaza tras reserva','Sí hay compensación: liberar unidades previamente reservadas.'],['Pago detenido / Kafka detenido','Queda pendiente para recuperación; una demora no equivale a cancelación.'],['Error en SQL dentro de una operación','Rollback local; distinto de compensación entre servicios.'],['Evento no procesable tras reintentos','DLT; requiere diagnóstico y reproceso, no curación infinita automática.']])+para('Dónde leer: InventarioEvents.reservar/liberar en Catálogo; VentaEvents en Venta; PagoEvents en Pago; Inbox, Outbox y MessagingConfiguration en la biblioteca común. El manejador Kafka configura reintentos y .DLT; consulta el código completo antes de afirmar que cualquier fallo se compensa automáticamente.'))
chapter('25. Etapa 14: Citas y reservas consistentes',para('Citas es transaccional por la operación de reserva. Crea cita y detalles y valida que la mascota pertenezca al cliente, la oferta esté disponible en esa sede y la profesional exista. Guarda precio/duración/componentes para preservar el acuerdo aunque cambien los maestros.')+para('Los bloqueos de agenda evitan dos reservas concurrentes que ocupen el mismo intervalo de una profesional. No es suficiente ocultar horas en Angular: dos navegadores podrían confirmar a la vez. Las reglas de fecha futura y intervalos se validan también en el backend.')+steps(['Copia la etapa 14 y sus migraciones.','Consulta CitaService: identifica cada llamada a Usuario, Institución y Bienestar.','Como cliente con mascota propia, selecciona sede, profesional y prestación/paquete.','Reserva y verifica el resultado. Intenta otro horario solapado: debe rechazarse con un error de negocio.','Como ADMIN usa las operaciones de gestión permitidas; como cliente no accedas a citas ajenas cambiando el id.'])+para('Citas no forma parte automáticamente de la Saga de compra. Su atomicidad principal es local y sus referencias se consultan mediante HTTP acotado. No prometas compensación de un pago de cita que el código no implementa.'))
chapter('26. Etapa 15: Gateway y rutas de negocio',para('Crea infra/garritas-gateway y pega el YAML de rutas del config-repo ya creado. Usa el starter MVC del proyecto. No mezcles configuración WebFlux con esta implementación.')+table(['Ruta por Gateway','Destino lógico'],[['/api/v1/productos y /categorias','garritas-catalogo-ms'],['/api/v1/ventas y /envios y /despachos','garritas-venta-ms'],['/api/v1/sedes y /prestaciones','garritas-institucion-ms'],['/api/v1/transportistas y /zonas y /coberturas','garritas-envio-ms'],['/api/v1/usuarios y /mascotas y /roles y /planes y /suscripciones','garritas-usuario-ms'],['/api/v1/citas','garritas-citas-ms'],['/api/v1/pagos','garritas-pago-ms'],['/api/v1/especialistas y /especialidades','garritas-bienestar-ms']])+para('lb://garritas-venta-ms se resuelve con Eureka; no es una URL que abre el navegador. Gateway aplica JWT y CORS; cada microservicio vuelve a validar el JWT para impedir acceso directo sin autorización.')+pre('''Invoke-RestMethod http://localhost:18080/api/v1/productos
Invoke-WebRequest -UseBasicParsing http://localhost:18080/api/v1/ventas''')+para('La lectura pública de productos debe responder cuando el sistema esté activo. La segunda consulta sin token debe ser rechazada (401), no entregar ventas de todos los usuarios. CORS controla navegadores, no reemplaza autenticación.'))
chapter('27. Etapa 16: crear Angular y conectar la API',para('La aplicación real utiliza componentes standalone. No busques app.module.ts: el arranque está en src/main.ts y la configuración de proveedores en src/app/app.config.ts. Copia la etapa 16 completa; así conservas package.json, package-lock.json y la estructura que coincide con este backend.')+para('Para reconocer cómo se genera un proyecto nuevo, Angular CLI permite ng new. Este comando es una alternativa de esqueleto, no se ejecuta encima de los archivos ya copiados:')+pre('''# Solo si eliges generar un esqueleto antes de sustituirlo por el código exacto.
# Ejecutar desde clients con la carpeta garritas-frontend aún inexistente.
npx.cmd --package @angular/cli@22.1.8 ng new garritas-frontend --standalone --routing --style=css --skip-git --skip-install''')+para('Después de generar, sustituye los archivos por sus versiones del anexo y elimina archivos de ejemplo que entren en conflicto. La ruta recomendada para reproducir es copiar la etapa 16 directamente, sin generar una segunda aplicación.')+table(['Archivo','Qué debes entender'],[['src/main.ts / app.config.ts','bootstrapApplication y proveedores; inicializa configuración y autenticación.'],['public/config.dev.json','API Gateway, URL de Keycloak, realm y clientId para DEV.'],['core/config.ts','Carga configuración antes de utilizarla.'],['core/auth.ts','keycloak-js, PKCE, sesión, renovación y roles.'],['core/interceptor.ts','Añade Bearer a la API propia; no envía el token a cualquier URL.'],['core/api.ts / domain-api.ts','Métodos HTTP y tipos; evitan URL repetidas en cada pantalla.'],['app.ts / app.html','Navegación, checkout, pedidos y coordinación de vistas.'],['features/*','Componentes de cada dominio.'],['src/styles.css','Estilos globales y presentación adaptable.']])+pre('''cd clients/garritas-frontend
$env:NG_CLI_ANALYTICS = "false"
npm.cmd ci
npm.cmd run build
npm.cmd test
# Para levantar solo Angular mientras los backend ya están activos:
npm.cmd start''')+note('No ejecutes npm start si el lanzador ya abrió Angular en 4200. Si Angular pregunta por analítica (y/N), responde N y Enter. No ejecutes npm audit fix --force sin revisar cambios de versiones.'))
chapter('28. Frontend: pantalla por pantalla y lógica correcta',table(['Pantalla','Ruta bajo clients/garritas-frontend/src/app/','Comprobación'],[['Catálogo','features/catalogo/product-catalog.html y .ts','Filtrar categorías, ver producto y stock.'],['Carrito','features/cart/cart-panel.html, cart-panel.ts, cart-store.ts','Cantidad válida, sede, entrega y total. ADMIN sin compra.'],['Pedidos','app.html y app.ts','Vista pedidos; refreshVentas y checkout; estados pendientes visibles.'],['Sedes','features/sedes/sedes.component.html y .ts','ADMIN edita; cliente consulta/selecciona.'],['Prestaciones / paquetes','features/prestaciones/prestaciones.component.html y .ts','Oferta por sede y componentes válidos.'],['Cuenta / mascotas','features/cuenta/cuenta.component.html y .ts','Guardar, volver a cargar y comprobar persistencia; DIAS/MESES.'],['Planes / suscripciones','features/planes/planes.component.html y .ts','Contratar/renovar/cancelar; historial.'],['Citas','features/citas/citas.component.html y .ts','Propiedad, oferta y solapamiento.'],['Logística / Envíos','features/logistica/ y features/envios/','Maestros de tarifa versus despacho de Venta.'],['Administración','features/admin/','Roles efectivos emitidos por Keycloak, no por una lista manipulable del navegador.']])+para('Para cambiar letras de Citas abre src/styles.css y añade un selector acotado. Ejemplo de personalización opcional, posterior a reproducir la base:')+pre('''app-citas h1 {
  font-size: 1.8rem;
}
app-citas label {
  font-size: 1rem;
}''','css')+para('Para Pedidos, busca en app.html el bloque @if(view()===\'pedidos\'). @for(v of ventas(); track v.id) crea cada tarjeta. El botón Actualizar invoca refreshVentas() en app.ts; core/api.ts hace GET /ventas. Cambiar HTML modifica presentación, no los estados autorizados del backend.'))
chapter('29. Etapa 17: Prometheus, Loki y Grafana',para('Crea obs con todos los YAML y JSON. Prometheus recoge métricas; Loki almacena logs; Promtail envía los archivos de .runtime; Grafana presenta consultas de ambas fuentes. El dashboard se provisiona desde archivos versionados, no se construye a mano cada vez.')+pre('''# Primero inicia Keycloak: observabilidad usa su red externa.
docker compose -f obs/compose-dev.yml up -d
Start-Process "http://localhost:13000"
Start-Process "http://localhost:19090"''')+para('Grafana: admin / local-grafana si no se cambió la contraseña persistida. Abre Dashboards → Garritas → Garritas - Infraestructura. Consulta instancias, peticiones, conexiones PostgreSQL y logs. No existe automáticamente un panel visual de Keycloak solo por arrancar Grafana.')+pre('''up
up{job="garritas-microservicios"}
up{job="keycloak"}''','promql')+para('En Prometheus pega una consulta y pulsa Execute; 1 indica scrape correcto, 0 fallo, ausencia de serie puede indicar un job no cargado. En /targets identifica el error. En Grafana → Explore → Prometheus puedes ejecutar las mismas consultas. Para Keycloak se recoge /metrics por su puerto de gestión 9000 en Docker.')+pre('''{application=~"garritas-(venta|catalogo|pago)-ms"} |= "TRACE_ID"''','logql')+para('En Explore → Loki sustituye TRACE_ID por el valor real X-Trace-ID de una operación. Así correlacionas mensajes de servicios diferentes. No es un sistema de trazas OpenTelemetry: son logs correlacionados.'))
chapter('30. Etapa 18: scripts, pruebas y Docker integrado',para('Copia uso-rapido, .github/workflows y el resto de la etapa. El reactor uso-rapido/pom.xml enumera 13 módulos de construcción: biblioteca común, tres aplicaciones de infraestructura, ocho dominios y agregador. No son 13 microservicios de negocio.')+para('garritas.ps1 implementa build, iniciar, estado, detener y test. iniciar levanta dependencias Docker, luego Java en orden y finalmente Angular, y registra PID y fecha de inicio. detener cierra únicamente esos procesos registrados; las bases se conservan.')+para('La carpeta uso-rapido/docker contiene un despliegue integrado alternativo con imágenes. No lo mezcles con DEV usando los mismos puertos. Este manual ejecuta DEV; lee su README y resuelve nombres/issuer de red si eliges otra topología.')+para('La carpeta garritas-eventos-py es un ejemplo de productor/consumidor, no reemplaza los consumidores de la Saga Java. Los scripts de humo, fallos y resiliencia sirven para verificar escenarios; lee sus requisitos y efectos antes de ejecutarlos sobre datos de demostración.')+para('CI ejecuta empaquetado Java, validación Compose y pruebas/build Angular. El job Java actual usa -DskipTests al empaquetar: una marca verde de ese job no prueba por sí sola todos los escenarios de negocio.'))
PORTS=[('Angular',4200,'http://localhost:4200','Tienda y administración'),('Gateway',18080,'http://localhost:18080/api/v1/productos','API; no portada web'),('Config',18888,'http://localhost:18888/garritas-catalogo-ms/dev','Configuración'),('Eureka',18761,'http://localhost:18761','Registro'),('Kafka broker',19092,'TCP; no es página web','Clientes Java del host'),('Kafka UI',18085,'http://localhost:18085','Topics y grupos'),('Keycloak',18180,'http://localhost:18180/admin/','Identidad'),('Keycloak métricas',19000,'http://localhost:19000/metrics','Puerto de gestión mapeado a 9000'),('Grafana',13000,'http://localhost:13000','Dashboard / Explore'),('Prometheus',19090,'http://localhost:19090/targets','Targets'),('Loki',13100,'http://localhost:13100/ready','API de logs, no tienda')]
DPORTS=[('Venta',8081,15441,'venta'),('Institución',8082,15442,'institucion'),('Envío',8083,15443,'envio'),('Citas',8084,15444,'citas'),('Catálogo',8085,15445,'catalogo'),('Usuario',8086,15446,'usuario'),('Pago',8087,15447,'pago'),('Bienestar',8088,15448,'bienestar')]
