cover=f'<div class="cover"><p class="eyebrow">CONSTRUIR · ENTENDER · COMPROBAR</p><h1>Garritas Store<br>Desde una carpeta vacía</h1><p>Manual de construcción paso a paso, con rutas exactas, código completo y pruebas.</p><p>18 etapas · ocho dominios · Angular · Keycloak · Kafka · observabilidad</p><p class="small">Referencia de código: {FULL}<br>Edición: noviembre de 2026 · Windows PowerShell</p></div>'
toc='<nav class="toc"><h2>Índice: leer en orden</h2>'+''.join(f'<a href="#c{i}">{esc(t)}</a>' for i,(t,b) in enumerate(CH,1))+'</nav>'
body=cover+toc+''.join(f'<section class="chapter" id="c{i}"><h1>{esc(t)}</h1>{b}</section>' for i,(t,b) in enumerate(CH,1))
